"use strict";(self.webpackChunk_repo_brand=self.webpackChunk_repo_brand||[]).push([[905],{"./stories/guide/01-principles.mdx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.r(__webpack_exports__),__webpack_require__.d(__webpack_exports__,{default:()=>MDXContent});__webpack_require__("../../node_modules/next/dist/compiled/react/index.js");var jsx_runtime=__webpack_require__("../../node_modules/next/dist/compiled/react/jsx-runtime.js"),lib=__webpack_require__("../../node_modules/@mdx-js/react/lib/index.js"),blocks=__webpack_require__("../../node_modules/@storybook/addon-docs/dist/blocks.js");function _createMdxContent(props){return(0,jsx_runtime.jsxs)(jsx_runtime.Fragment,{children:[(0,jsx_runtime.jsx)(blocks.W8,{title:"Guide/Principles"}),"\n",(0,jsx_runtime.jsx)(blocks.oz,{children:"# Brand and Identity\n\nThe Society's design system: its logo, colors and type, used with restraint and in one language at a time. Less ink, more page.\n\nFor the Director of Media, the Design Lead and anyone making something with the Society's name on it. SAL-BRD-01, Version 1, ratified on Charter Day, Tuesday, October 13, 2026; prepared by Shaheen Farjo, Founder and President. The Director of Media owns it; it is reviewed each September.\n\n## Modern page, old pen\n\nA society about writing should look like the best-made page on campus: wide margins, light type, one crimson mark. Modern in its restraint, literary in its words, and plainly part of AUIB.\n\n| Principle | |\n| --- | --- |\n| **Quiet by default** | White space, hairline rules and sentence case carry the page. Each page gets one loud thing: a headline, one crimson word or one band of color. If two things compete, remove one. |\n| **One language per piece** | Every page, post and document is in English or in Arabic, with the logo in that language. The two editions are equals, set in the same family, Ubuntu and Ubuntu Arabic, each written for its own readers and checked by a native speaker. Never both on one piece. |\n| **The page is the brand** | The symbol is a bookmark, and it appears only as the logo. Everything else is built from what a book is made of: pages, margins, rules and type. Titles stand alone: no markers, ribbons or labels above them. No gradients, no shadows; icons carry meaning, never decoration. |\n\n## The motto\n\n**The paper and the pen.** A line of al-Mutanabbi. On Arabic pieces it appears in his words: «والقرطاسُ والقلم».\n"})]})}function MDXContent(props={}){const{wrapper:MDXLayout}={...(0,lib.R)(),...props.components};return MDXLayout?(0,jsx_runtime.jsx)(MDXLayout,{...props,children:(0,jsx_runtime.jsx)(_createMdxContent,{...props})}):_createMdxContent()}}}]);
